INSERT INTO {PID}.A_G_LN_CREDIT_CARD_ACCT_SUM(\n DATA_DT                                  \n,ORG_NO                                   \n,LP_NO                                      \n,ACCT_TYPE                               \n,CURRCY_CD                                \n,OVERDUE_SETOU                            \n,ACCT_STS                                 \n,NP_IND                                   \n,WHE_THE_YEAR_VRFCTN                      \n,BEGIN_YEAR_NP_IND                       \n,ACCT_CLOSE_CD                            \n,APPL_CD                                  \n,PROD_NO                                  \n,OVERDUE_TYPE                             \n,FIVECLASS_CLASS                          \n,CREDIT_LIMIT                             \n,CONSM_BAL                                \n,CASH_WITHD_BAL                           \n,BAL                                      \n,CREDIT_CARD_OVER_PAY_BAL                 \n,STAGES_BAL                               \n,CREDIT_CARD_OVERD_BAL                    \n,CREDIT_CARD_ITEM_BAL                     \n,CREDIT_CARD_LOAN_MONTH_CALCU_BASE        \n,CREDIT_CARD_LOAN_QUART_CALCU_BASE        \n,CREDIT_CARD_LOAN_YEAR_CALCU_BASE         \n,CREDIT_CARD_ITEM_MONTH_CALCU_BASE        \n,CREDIT_CARD_ITEM_QUART_CALCU_BASE        \n,CREDIT_CARD_ITEM_YEAR_CALCU_BASE         \n,CREDIT_CARD_STAGES_MONTH_CALCU_BASE      \n,CREDIT_CARD_STAGES_QUART_CALCU_BASE      \n,CREDIT_CARD_STAGES_YEAR_CALCU_BASE       \n,CREDIT_CARD_OVERD_MONTH_CALCU_BASE       \n,CREDIT_CARD_OVERD_QUART_CALCU_BASE       \n,CREDIT_CARD_OVERD_YEAR_CALCU_BASE        \n,CREDIT_CARD_WITHD_MONTH_CALCU_BASE       \n,CREDIT_CARD_WITHD_QUART_CALCU_BASE       \n,CREDIT_CARD_WITHD_YEAR_CALCU_BASE        \n,CREDIT_CARD_LOAN_MONTH_DAILY_AVG         \n,CREDIT_CARD_LOAN_QUART_DAILY_AVG         \n,CREDIT_CARD_LOAN_YEAR_DAILY_AVG          \n,CREDIT_CARD_ITEM_MONTH_DAILY_AVG         \n,CREDIT_CARD_ITEM_QUART_DAILY_AVG         \n,CREDIT_CARD_ITEM_YEAR_DAILY_AVG          \n,CREDIT_CARD_STAGES_MONTH_DAILY_AVG       \n,CREDIT_CARD_STAGES_QUART_DAILY_AVG       \n,CREDIT_CARD_STAGES_YEAR_DAILY_AVG        \n,CREDIT_CARD_OVERD_MONTH_DAILY_AVG        \n,CREDIT_CARD_OVERD_QUART_DAILY_AVG        \n,CREDIT_CARD_OVERD_YEAR_DAILY_AVG         \n,CREDIT_CARD_WITHD_MONTH_DAILY_AVG        \n,CREDIT_CARD_WITHD_QUART_DAILY_AVG        \n,CREDIT_CARD_WITHD_YEAR_DAILY_AVG         \n,CREDIT_CARD_LOAN_INTST_BAL                  \n,CREDIT_CARD_STAGES_INTST_INCOME             \n,CREDIT_CARD_OVERD_INTST_INCOME              \n,CREDIT_CARD_ITEM_STAGES_INTST_INCOME        \n,CREDIT_CARD_DEFAULT_INTST_INCOME            \n,CREDIT_CARD_LOAN_MONTH_INTST_INCOME         \n,CREDIT_CARD_STAGES_MONTH_INTST_INCOME       \n,CREDIT_CARD_OVERD_MONTH_INTST_INCOME        \n,CREDIT_CARD_ITEM_STAGES_MONTH_INTST_INCOME  \n,CREDIT_CARD_DEFAULT_MONTH_INTST_INCOME      \n,CREDIT_CARD_LOAN_QUART_INTST_INCOME         \n,CREDIT_CARD_STAGES_QUART_INTST_INCOME       \n,CREDIT_CARD_OVERD_QUART_INTST_INCOME        \n,CREDIT_CARD_ITEM_STAGES_QUART_INTST_INCOME  \n,CREDIT_CARD_DEFAULT_QUART_INTST_INCOME      \n,ACCTG_ORG                                   \n)\nSELECT \n T1.DATA_DT                                    AS DATA_DT                                   \n,case when T1.ORG_NO in ('0803','0804','0809') then '0898'\n      when t1.org_no = '0805' then '0802'\n      else T1.ORG_NO end                       AS ORG_NO                                    \n,'10000'                                       AS LP_NO                                     \n,T1.ACCT_CLASS                                 AS ACCT_CLASS                                \n,'001'                                  AS CURRCY_CD                                 \n,CAST(OVERDUE_SETOU AS DECIMAL(18,2))                                 AS OVERDUE_SETOU                            \n,T1.ACCT_STS                                   AS ACCT_STS                                  \n,T1.NP_IND                                     AS NP_IND                                    \n,T1.WHE_THE_YEAR_VRFCTN                        AS WHE_THE_YEAR_VRFCTN                       \n,T1.BEGIN_YEAR_NP_FLAG                         AS BEGIN_YEAR_NP_FLAG                        \n,T1.ACCT_CLOSE_CD                                                                           \n,T1.APPL_CD                                    AS APPL_CD                                   \n,T1.PROD_NO                                    AS PROD_NO                                   \n,case when t1.OVERDUE_TERMS > 3 then '2'\n        when t1.OVERDUE_TERMS > 0 and t1.OVERDUE_TERMS <= 3  and T1.ORG_NO not like '08%' then '1'\n        when t1.OVERDUE_TERMS > 0 and t1.OVERDUE_TERMS <= 2  and T1.ORG_NO like '08%' then '1'\n        when t1.OVERDUE_TERMS > 2 and t1.OVERDUE_TERMS <= 3  and T1.ORG_NO like '08%' then '2'\n        else '0' \n        end                              AS OVERDUE_TYPE                              \n,T1.FIVECLASS_CLASS_CD                         AS FIVECLASS_CLASS                           \n,T1.CREDIT_LIMIT                               AS CREDIT_LIMIT                              \n,T1.CONSM_BAL                                  AS CONSM_BAL                                 \n,T1.CASH_WITHD_BAL                             AS CASH_WITHD_BAL                            \n,T1.CREDIT_CARD_LOAN_BAL                       AS BAL                                       \n,T1.CREDIT_CARD_OVER_PAY_BAL                   AS CREDIT_CARD_OVER_PAY_BAL                  \n,T1.CREDIT_CARD_STAGES_BAL                     AS CREDIT_CARD_STAGES_BAL                    \n,T1.CREDIT_CARD_OVERD_BAL                      AS CREDIT_CARD_OVERD_BAL                     \n,T1.CREDIT_CARD_ITEM_BAL                       AS CREDIT_CARD_ITEM_BAL                      \n,T1.CREDIT_CARD_LOAN_MONTH_CALCU_BASE          AS CREDIT_CARD_LOAN_MONTH_CALCU_BASE         \n,T1.CREDIT_CARD_LOAN_QUART_CALCU_BASE          AS CREDIT_CARD_LOAN_QUART_CALCU_BASE         \n,T1.CREDIT_CARD_LOAN_YEAR_CALCU_BASE           AS CREDIT_CARD_LOAN_YEAR_CALCU_BASE          \n,T1.CREDIT_CARD_ITEM_MONTH_CALCU_BASE          AS CREDIT_CARD_ITEM_MONTH_CALCU_BASE         \n,T1.CREDIT_CARD_ITEM_QUART_CALCU_BASE          AS CREDIT_CARD_ITEM_QUART_CALCU_BASE         \n,T1.CREDIT_CARD_ITEM_YEAR_CALCU_BASE           AS CREDIT_CARD_ITEM_YEAR_CALCU_BASE          \n,T1.CREDIT_CARD_STAGES_MONTH_CALCU_BASE        AS CREDIT_CARD_STAGES_MONTH_CALCU_BASE       \n,T1.CREDIT_CARD_STAGES_QUART_CALCU_BASE        AS CREDIT_CARD_STAGES_QUART_CALCU_BASE       \n,T1.CREDIT_CARD_STAGES_YEAR_CALCU_BASE         AS CREDIT_CARD_STAGES_YEAR_CALCU_BASE        \n,T1.CREDIT_CARD_OVERD_MONTH_CALCU_BASE         AS CREDIT_CARD_OVERD_MONTH_CALCU_BASE        \n,T1.CREDIT_CARD_OVERD_QUART_CALCU_BASE         AS CREDIT_CARD_OVERD_QUART_CALCU_BASE        \n,T1.CREDIT_CARD_OVERD_YEAR_CALCU_BASE          AS CREDIT_CARD_OVERD_YEAR_CALCU_BASE         \n,T1.CREDIT_CARD_WITHD_MONTH_CALCU_BASE         AS CREDIT_CARD_WITHD_MONTH_CALCU_BASE        \n,T1.CREDIT_CARD_WITHD_QUART_CALCU_BASE         AS CREDIT_CARD_WITHD_QUART_CALCU_BASE        \n,T1.CREDIT_CARD_WITHD_YEAR_CALCU_BASE          AS CREDIT_CARD_WITHD_YEAR_CALCU_BASE         \n,T1.CREDIT_CARD_LOAN_MONTH_DAILY_AVG           AS CREDIT_CARD_LOAN_MONTH_DAILY_AVG          \n,T1.CREDIT_CARD_LOAN_QUART_DAILY_AVG           AS CREDIT_CARD_LOAN_QUART_DAILY_AVG          \n,T1.CREDIT_CARD_LOAN_YEAR_DAILY_AVG            AS CREDIT_CARD_LOAN_YEAR_DAILY_AVG           \n,T1.CREDIT_CARD_ITEM_MONTH_DAILY_AVG           AS CREDIT_CARD_ITEM_MONTH_DAILY_AVG          \n,T1.CREDIT_CARD_ITEM_QUART_DAILY_AVG           AS CREDIT_CARD_ITEM_QUART_DAILY_AVG          \n,T1.CREDIT_CARD_ITEM_YEAR_DAILY_AVG            AS CREDIT_CARD_ITEM_YEAR_DAILY_AVG           \n,T1.CREDIT_CARD_STAGES_MONTH_DAILY_AVG         AS CREDIT_CARD_STAGES_MONTH_DAILY_AVG        \n,T1.CREDIT_CARD_STAGES_QUART_DAILY_AVG         AS CREDIT_CARD_STAGES_QUART_DAILY_AVG        \n,T1.CREDIT_CARD_STAGES_YEAR_DAILY_AVG          AS CREDIT_CARD_STAGES_YEAR_DAILY_AVG         \n,T1.CREDIT_CARD_OVERD_MONTH_DAILY_AVG          AS CREDIT_CARD_OVERD_MONTH_DAILY_AVG         \n,T1.CREDIT_CARD_OVERD_QUART_DAILY_AVG          AS CREDIT_CARD_OVERD_QUART_DAILY_AVG         \n,T1.CREDIT_CARD_OVERD_YEAR_DAILY_AVG           AS CREDIT_CARD_OVERD_YEAR_DAILY_AVG          \n,T1.CREDIT_CARD_WITHD_MONTH_DAILY_AVG          AS CREDIT_CARD_WITHD_MONTH_DAILY_AVG         \n,T1.CREDIT_CARD_WITHD_QUART_DAILY_AVG          AS CREDIT_CARD_WITHD_QUART_DAILY_AVG         \n,T1.CREDIT_CARD_WITHD_YEAR_DAILY_AVG           AS CREDIT_CARD_WITHD_YEAR_DAILY_AVG          \n,CREDIT_CARD_LOAN_INTST_BAL                    AS CREDIT_CARD_LOAN_INTST_BAL                  \n,CREDIT_CARD_STAGES_INTST_INCOME               AS CREDIT_CARD_STAGES_INTST_INCOME             \n,CREDIT_CARD_OVERD_INTST_INCOME                AS CREDIT_CARD_OVERD_INTST_INCOME              \n,CREDIT_CARD_ITEM_STAGES_INTST_INCOME          AS CREDIT_CARD_ITEM_STAGES_INTST_INCOME        \n,CREDIT_CARD_DEFAULT_INTST_INCOME              AS CREDIT_CARD_DEFAULT_INTST_INCOME            \n,CREDIT_CARD_LOAN_MONTH_INTST_INCOME           AS CREDIT_CARD_LOAN_MONTH_INTST_INCOME         \n,CREDIT_CARD_STAGES_MONTH_INTST_INCOME         AS CREDIT_CARD_STAGES_MONTH_INTST_INCOME       \n,CREDIT_CARD_OVERD_MONTH_INTST_INCOME          AS CREDIT_CARD_OVERD_MONTH_INTST_INCOME        \n,CREDIT_CARD_ITEM_STAGES_MONTH_INTST_INCOME    AS CREDIT_CARD_ITEM_STAGES_MONTH_INTST_INCOME  \n,CREDIT_CARD_DEFAULT_MONTH_INTST_INCOME        AS CREDIT_CARD_DEFAULT_MONTH_INTST_INCOME      \n,CREDIT_CARD_LOAN_QUART_INTST_INCOME           AS CREDIT_CARD_LOAN_QUART_INTST_INCOME         \n,CREDIT_CARD_STAGES_QUART_INTST_INCOME         AS CREDIT_CARD_STAGES_QUART_INTST_INCOME       \n,CREDIT_CARD_OVERD_QUART_INTST_INCOME          AS CREDIT_CARD_OVERD_QUART_INTST_INCOME        \n,CREDIT_CARD_ITEM_STAGES_QUART_INTST_INCOME    AS CREDIT_CARD_ITEM_STAGES_QUART_INTST_INCOME  \n,CREDIT_CARD_DEFAULT_QUART_INTST_INCOME        AS CREDIT_CARD_DEFAULT_QUART_INTST_INCOME      \n,ACCTG_ORG\nFROM (\n    SELECT  \n        DATE'{ETL_TX_DT}'                             AS DATA_DT                                   \n        ,t1.ORG_NO                                    AS ORG_NO                                    \n        ,T1.ACCT_CLASS                                        AS ACCT_CLASS                        \n        ,T1.CURRCY_CD                                         AS CURRCY_CD                         \n        ,SUM(CASE WHEN T1.DATA_DT = DATE '{ETL_TX_DT}' THEN T1.OVERDUE_SETOU ELSE 0 END)         AS OVERDUE_SETOU                    \n        ,T1.ACCT_STS                                          AS ACCT_STS                          \n        ,T1.NP_IND                                            AS NP_IND                            \n        ,CASE WHEN SUBSTR(T1.CLOSE_CHDY,1,4) \n         =SUBSTR('{ETL_TX_DT}',1,4) THEN 'Y' ELSE 'N'  END      AS WHE_THE_YEAR_VRFCTN               \n         ,T1.BEGIN_YEAR_NP_IND                                AS BEGIN_YEAR_NP_FLAG                \n         ,T1.ACCT_CLOSE_CD                                                                       \n\t\t ,T1.APPL_CD                                          AS APPL_CD                         \n         ,T1.PROD_NO                                          AS PROD_NO                         \n         ,T1.OVERDUE_TERMS                                    AS OVERDUE_TERMS                \n         ,T1.FIVECLASS_CLASS_CD                               AS FIVECLASS_CLASS_CD                \n        ,SUM(CASE WHEN T1.DATA_DT = DATE '{ETL_TX_DT}' THEN T1.CREDIT_LIMIT ELSE 0 END)                         AS CREDIT_LIMIT                              \n        ,SUM(CASE WHEN T1.DATA_DT = DATE '{ETL_TX_DT}' THEN t1.CONSM_BAL ELSE 0 END)                            AS CONSM_BAL                                 \n        ,SUM(CASE WHEN T1.DATA_DT = DATE '{ETL_TX_DT}' THEN t1.CASH_WITHD_BAL ELSE 0 END)                       AS CASH_WITHD_BAL                            \n        ,SUM(CASE WHEN T1.DATA_DT = DATE '{ETL_TX_DT}' THEN t1.TOT_BAL ELSE 0 END)                              AS CREDIT_CARD_LOAN_BAL                      \n        ,SUM(CASE WHEN T1.DATA_DT = DATE '{ETL_TX_DT}' THEN t1.OVER_PAY ELSE 0 END)                             AS CREDIT_CARD_OVER_PAY_BAL                  \n        ,SUM(CASE WHEN T1.DATA_DT = DATE '{ETL_TX_DT}' THEN t1.CREDIT_CARD_STAGES_BAL ELSE 0 END)               AS CREDIT_CARD_STAGES_BAL                    \n        ,SUM(CASE WHEN T1.DATA_DT = DATE '{ETL_TX_DT}' THEN t1.CREDIT_CARD_OVERD_BAL ELSE 0 END)                AS CREDIT_CARD_OVERD_BAL                     \n        ,SUM(CASE WHEN T1.DATA_DT = DATE '{ETL_TX_DT}' THEN t1.CREDIT_CARD_ITEM_BAL ELSE 0 END)                 AS CREDIT_CARD_ITEM_BAL                      \n        ,sum(CASE WHEN T1.DATA_DT >= DATE '{I_MB_DT}' AND T1.DATA_DT <= DATE '{ETL_TX_DT}' THEN TOT_BAL ELSE 0 end)                                 AS CREDIT_CARD_LOAN_MONTH_CALCU_BASE          \n        ,sum(CASE WHEN T1.DATA_DT >= DATE '{I_QB_DT}' AND T1.DATA_DT <= DATE '{ETL_TX_DT}' THEN TOT_BAL  ELSE 0 end)                                AS CREDIT_CARD_LOAN_QUART_CALCU_BASE         \n        ,sum(CASE WHEN T1.DATA_DT >= DATE '{I_YB_DT}' AND T1.DATA_DT <= DATE '{ETL_TX_DT}' THEN TOT_BAL  ELSE 0 end)                                AS CREDIT_CARD_LOAN_YEAR_CALCU_BASE          \n        ,sum(CASE WHEN T1.DATA_DT >= DATE '{I_MB_DT}' AND T1.DATA_DT <= DATE '{ETL_TX_DT}' THEN CREDIT_CARD_ITEM_BAL  ELSE 0 end)                   AS CREDIT_CARD_ITEM_MONTH_CALCU_BASE         \n        ,sum(CASE WHEN T1.DATA_DT >= DATE '{I_QB_DT}' AND T1.DATA_DT <= DATE '{ETL_TX_DT}' THEN CREDIT_CARD_ITEM_BAL  ELSE 0 end)                   AS CREDIT_CARD_ITEM_QUART_CALCU_BASE         \n        ,sum(CASE WHEN T1.DATA_DT >= DATE '{I_YB_DT}' AND T1.DATA_DT <= DATE '{ETL_TX_DT}' THEN CREDIT_CARD_ITEM_BAL  ELSE 0 end)                   AS CREDIT_CARD_ITEM_YEAR_CALCU_BASE          \n        ,sum(CASE WHEN T1.DATA_DT >= DATE '{I_MB_DT}' AND T1.DATA_DT <= DATE '{ETL_TX_DT}' THEN CREDIT_CARD_STAGES_BAL  ELSE 0 end)                 AS CREDIT_CARD_STAGES_MONTH_CALCU_BASE       \n        ,sum(CASE WHEN T1.DATA_DT >= DATE '{I_QB_DT}' AND T1.DATA_DT <= DATE '{ETL_TX_DT}' THEN CREDIT_CARD_STAGES_BAL  ELSE 0 end)                 AS CREDIT_CARD_STAGES_QUART_CALCU_BASE       \n        ,sum(CASE WHEN T1.DATA_DT >= DATE '{I_YB_DT}' AND T1.DATA_DT <= DATE '{ETL_TX_DT}' THEN CREDIT_CARD_STAGES_BAL  ELSE 0 end)                 AS CREDIT_CARD_STAGES_YEAR_CALCU_BASE        \n        ,sum(CASE WHEN T1.DATA_DT >= DATE '{I_MB_DT}' AND T1.DATA_DT <= DATE '{ETL_TX_DT}' THEN CREDIT_CARD_OVERD_BAL  ELSE 0 end)                  AS CREDIT_CARD_OVERD_MONTH_CALCU_BASE        \n        ,sum(CASE WHEN T1.DATA_DT >= DATE '{I_QB_DT}' AND T1.DATA_DT <= DATE '{ETL_TX_DT}' THEN CREDIT_CARD_OVERD_BAL  ELSE 0 end)                  AS CREDIT_CARD_OVERD_QUART_CALCU_BASE        \n        ,sum(CASE WHEN T1.DATA_DT >= DATE '{I_YB_DT}' AND T1.DATA_DT <= DATE '{ETL_TX_DT}' THEN CREDIT_CARD_OVERD_BAL  ELSE 0 end)                  AS CREDIT_CARD_OVERD_YEAR_CALCU_BASE         \n        ,sum(CASE WHEN T1.DATA_DT >= DATE '{I_MB_DT}' AND T1.DATA_DT <= DATE '{ETL_TX_DT}' THEN CASH_WITHD_BAL  ELSE 0 end)                         AS CREDIT_CARD_WITHD_MONTH_CALCU_BASE        \n        ,sum(CASE WHEN T1.DATA_DT >= DATE '{I_QB_DT}' AND T1.DATA_DT <= DATE '{ETL_TX_DT}' THEN CASH_WITHD_BAL  ELSE 0 end)                         AS CREDIT_CARD_WITHD_QUART_CALCU_BASE        \n        ,sum(CASE WHEN T1.DATA_DT >= DATE '{I_YB_DT}' AND T1.DATA_DT <= DATE '{ETL_TX_DT}' THEN CASH_WITHD_BAL  ELSE 0 end)                         AS CREDIT_CARD_WITHD_YEAR_CALCU_BASE         \n        ,sum(CASE WHEN T1.DATA_DT >= DATE '{I_MB_DT}' AND T1.DATA_DT <= DATE '{ETL_TX_DT}' THEN TOT_BAL  ELSE 0 end)                / {MTD_DAYS}    AS CREDIT_CARD_LOAN_MONTH_DAILY_AVG          \n        ,sum(CASE WHEN T1.DATA_DT >= DATE '{I_QB_DT}' AND T1.DATA_DT <= DATE '{ETL_TX_DT}' THEN TOT_BAL  ELSE 0 end)                / {QTD_DAYS}    AS CREDIT_CARD_LOAN_QUART_DAILY_AVG          \n        ,sum(CASE WHEN T1.DATA_DT >= DATE '{I_YB_DT}' AND T1.DATA_DT <= DATE '{ETL_TX_DT}' THEN TOT_BAL  ELSE 0 end)                / {YTD_DAYS}    AS CREDIT_CARD_LOAN_YEAR_DAILY_AVG           \n        ,sum(CASE WHEN T1.DATA_DT >= DATE '{I_MB_DT}' AND T1.DATA_DT <= DATE '{ETL_TX_DT}' THEN CREDIT_CARD_ITEM_BAL  ELSE 0 end)   / {MTD_DAYS}    AS CREDIT_CARD_ITEM_MONTH_DAILY_AVG          \n        ,sum(CASE WHEN T1.DATA_DT >= DATE '{I_QB_DT}' AND T1.DATA_DT <= DATE '{ETL_TX_DT}' THEN CREDIT_CARD_ITEM_BAL  ELSE 0 end)   / {QTD_DAYS}    AS CREDIT_CARD_ITEM_QUART_DAILY_AVG          \n        ,sum(CASE WHEN T1.DATA_DT >= DATE '{I_YB_DT}' AND T1.DATA_DT <= DATE '{ETL_TX_DT}' THEN CREDIT_CARD_ITEM_BAL  ELSE 0 end)   / {YTD_DAYS}    AS CREDIT_CARD_ITEM_YEAR_DAILY_AVG           \n        ,sum(CASE WHEN T1.DATA_DT >= DATE '{I_MB_DT}' AND T1.DATA_DT <= DATE '{ETL_TX_DT}' THEN CREDIT_CARD_STAGES_BAL  ELSE 0 end) / {MTD_DAYS}    AS CREDIT_CARD_STAGES_MONTH_DAILY_AVG        \n        ,sum(CASE WHEN T1.DATA_DT >= DATE '{I_QB_DT}' AND T1.DATA_DT <= DATE '{ETL_TX_DT}' THEN CREDIT_CARD_STAGES_BAL  ELSE 0 end) / {QTD_DAYS}    AS CREDIT_CARD_STAGES_QUART_DAILY_AVG        \n        ,sum(CASE WHEN T1.DATA_DT >= DATE '{I_YB_DT}' AND T1.DATA_DT <= DATE '{ETL_TX_DT}' THEN CREDIT_CARD_STAGES_BAL  ELSE 0 end) / {YTD_DAYS}    AS CREDIT_CARD_STAGES_YEAR_DAILY_AVG         \n        ,sum(CASE WHEN T1.DATA_DT >= DATE '{I_MB_DT}' AND T1.DATA_DT <= DATE '{ETL_TX_DT}' THEN CREDIT_CARD_OVERD_BAL  ELSE 0 end)  / {MTD_DAYS}    AS CREDIT_CARD_OVERD_MONTH_DAILY_AVG         \n        ,sum(CASE WHEN T1.DATA_DT >= DATE '{I_QB_DT}' AND T1.DATA_DT <= DATE '{ETL_TX_DT}' THEN CREDIT_CARD_OVERD_BAL  ELSE 0 end)  / {QTD_DAYS}    AS CREDIT_CARD_OVERD_QUART_DAILY_AVG         \n        ,sum(CASE WHEN T1.DATA_DT >= DATE '{I_YB_DT}' AND T1.DATA_DT <= DATE '{ETL_TX_DT}' THEN CREDIT_CARD_OVERD_BAL  ELSE 0 end)  / {YTD_DAYS}    AS CREDIT_CARD_OVERD_YEAR_DAILY_AVG          \n        ,sum(CASE WHEN T1.DATA_DT >= DATE '{I_MB_DT}' AND T1.DATA_DT <= DATE '{ETL_TX_DT}' THEN CASH_WITHD_BAL  ELSE 0 end)  / {MTD_DAYS}           AS CREDIT_CARD_WITHD_MONTH_DAILY_AVG         \n        ,sum(CASE WHEN T1.DATA_DT >= DATE '{I_QB_DT}' AND T1.DATA_DT <= DATE '{ETL_TX_DT}' THEN CASH_WITHD_BAL  ELSE 0 end)  / {QTD_DAYS}           AS CREDIT_CARD_WITHD_QUART_DAILY_AVG         \n        ,sum(CASE WHEN T1.DATA_DT >= DATE '{I_YB_DT}' AND T1.DATA_DT <= DATE '{ETL_TX_DT}' THEN CASH_WITHD_BAL  ELSE 0 end)  / {YTD_DAYS}           AS CREDIT_CARD_WITHD_YEAR_DAILY_AVG          \n        ,sum(DEFAULT_DAY_INTST+STAGES_DAY_INTST+OVERD_DAY_INTST)                                  AS CREDIT_CARD_LOAN_INTST_BAL                  \n        ,sum(STAGES_DAY_INTST)                                                                    AS CREDIT_CARD_STAGES_INTST_INCOME             \n        ,sum(OVERD_DAY_INTST)                                                                     AS CREDIT_CARD_OVERD_INTST_INCOME              \n        ,sum(ITEM_STAGES_DAY_INTST)                                                               AS CREDIT_CARD_ITEM_STAGES_INTST_INCOME        \n        ,sum(DEFAULT_DAY_INTST)                                                                   AS CREDIT_CARD_DEFAULT_INTST_INCOME            \n        ,sum(CASE WHEN T1.DATA_DT >= DATE '{I_MB_DT}' AND T1.DATA_DT <= DATE '{ETL_TX_DT}' \n\t\t          THEN DEFAULT_DAY_INTST+STAGES_DAY_INTST+OVERD_DAY_INTST  ELSE 0 end)            AS CREDIT_CARD_LOAN_MONTH_INTST_INCOME         \n        ,sum(CASE WHEN T1.DATA_DT >= DATE '{I_MB_DT}' AND T1.DATA_DT <= DATE '{ETL_TX_DT}' \n\t\t          THEN STAGES_DAY_INTST ELSE 0 end)                                               AS CREDIT_CARD_STAGES_MONTH_INTST_INCOME       \n        ,sum(CASE WHEN T1.DATA_DT >= DATE '{I_MB_DT}' AND T1.DATA_DT <= DATE '{ETL_TX_DT}' \n\t\t          THEN OVERD_DAY_INTST ELSE 0 end)                                                AS CREDIT_CARD_OVERD_MONTH_INTST_INCOME        \n        ,sum(CASE WHEN T1.DATA_DT >= DATE '{I_MB_DT}' AND T1.DATA_DT <= DATE '{ETL_TX_DT}' \n\t\t          THEN ITEM_STAGES_DAY_INTST ELSE 0 end)                                          AS CREDIT_CARD_ITEM_STAGES_MONTH_INTST_INCOME  \n        ,sum(CASE WHEN T1.DATA_DT >= DATE '{I_MB_DT}' AND T1.DATA_DT <= DATE '{ETL_TX_DT}' \n\t\t          THEN DEFAULT_DAY_INTST ELSE 0 end)                                              AS CREDIT_CARD_DEFAULT_MONTH_INTST_INCOME      \n        ,sum(CASE WHEN T1.DATA_DT >= DATE '{I_QB_DT}' AND T1.DATA_DT <= DATE '{ETL_TX_DT}' \n\t\t          THEN DEFAULT_DAY_INTST+STAGES_DAY_INTST+OVERD_DAY_INTST  ELSE 0 end)            AS CREDIT_CARD_LOAN_QUART_INTST_INCOME         \n        ,sum(CASE WHEN T1.DATA_DT >= DATE '{I_QB_DT}' AND T1.DATA_DT <= DATE '{ETL_TX_DT}' \n\t\t          THEN STAGES_DAY_INTST ELSE 0 end)                                               AS CREDIT_CARD_STAGES_QUART_INTST_INCOME       \n        ,sum(CASE WHEN T1.DATA_DT >= DATE '{I_QB_DT}' AND T1.DATA_DT <= DATE '{ETL_TX_DT}' \n\t\t          THEN OVERD_DAY_INTST ELSE 0 end)                                                AS CREDIT_CARD_OVERD_QUART_INTST_INCOME        \n        ,sum(CASE WHEN T1.DATA_DT >= DATE '{I_QB_DT}' AND T1.DATA_DT <= DATE '{ETL_TX_DT}' \n\t\t          THEN ITEM_STAGES_DAY_INTST ELSE 0 end)                                          AS CREDIT_CARD_ITEM_STAGES_QUART_INTST_INCOME  \n        ,sum(CASE WHEN T1.DATA_DT >= DATE '{I_QB_DT}' AND T1.DATA_DT <= DATE '{ETL_TX_DT}' \n\t\t          THEN DEFAULT_DAY_INTST ELSE 0 end)                                              AS CREDIT_CARD_DEFAULT_QUART_INTST_INCOME      \n        ,ACCTG_ORG\n    FROM {PID}.A_D_LN_CREDIT_CARD_ACCT_INF t1          \n    WHERE T1.DATA_DT >= DATE '{I_YB_DT}'  and T1.DATA_DT <= DATE '{ETL_TX_DT}'\n    GROUP BY t1.ORG_NO,t1.ACCT_CLASS,t1.CURRCY_CD,T1.OVERDUE_SETOU,t1.ACCT_STS,t1.NP_IND,T1.OVERDUE_TERMS,T1.FIVECLASS_CLASS_CD,T1.BEGIN_YEAR_NP_IND,T1.ACCT_CLOSE_CD,APPL_CD,PROD_NO\n    ,CASE WHEN SUBSTR(T1.CLOSE_CHDY,1,4) =SUBSTR('{ETL_TX_DT}',1,4) THEN 'Y' ELSE 'N'  END,ACCTG_ORG\n) T1
